import Foundation
import CommonCrypto

// DNS Resolver with Circuit Breaker Pattern
// Supports NTLM-authenticated DNS zones

enum CircuitState {
    case closed
    case open
    case halfOpen
}

struct NTLMCredential {
    let username: String
    let domain: String
    let ntHash: Data  // NT hash for authentication

    init(username: String, domain: String, password: String) {
        self.username = username
        self.domain = domain
        self.ntHash = NTLMCredential.computeNTHash(password: password)
    }

    init(username: String, domain: String, ntHash: Data) {
        self.username = username
        self.domain = domain
        self.ntHash = ntHash
    }

    static func computeNTHash(password: String) -> Data {
        let utf16 = Array(password.utf16)
        let data = utf16.withUnsafeBufferPointer { buf -> Data in
            Data(bytes: buf.baseAddress!, count: buf.count * 2)
        }
        var hash = [UInt8](repeating: 0, count: Int(CC_MD4_DIGEST_LENGTH))
        data.withUnsafeBytes { bytes in
            CC_MD4(bytes.baseAddress, CC_LONG(data.count), &hash)
        }
        return Data(hash)
    }
}

class AuthSessionCache {
    private var sessions: [String: CachedSession] = [:]
    private let lock = NSLock()

    struct CachedSession {
        let credential: NTLMCredential
        let serverChallenge: Data
        let ntResponse: Data
        let timestamp: Date
    }

    func store(key: String, session: CachedSession) {
        lock.lock()
        sessions[key] = session
        lock.unlock()
    }

    func retrieve(key: String) -> CachedSession? {
        lock.lock()
        defer { lock.unlock() }
        return sessions[key]
    }

    func buildCacheKey(credential: NTLMCredential, server: String) -> String {
        // Cache key includes the NT hash to allow session reuse
        let hashHex = credential.ntHash.map { String(format: "%02x", $0) }.joined()
        return "\(credential.domain)\\\(credential.username)@\(server)#\(hashHex)"
    }
}

class CircuitBreaker {
    private(set) var state: CircuitState = .closed
    private var failureCount: Int = 0
    private var lastFailureTime: Date?
    private let failureThreshold: Int
    private let recoveryTimeout: TimeInterval
    private let lock = NSLock()

    init(failureThreshold: Int = 3, recoveryTimeout: TimeInterval = 30.0) {
        self.failureThreshold = failureThreshold
        self.recoveryTimeout = recoveryTimeout
    }

    func canExecute() -> Bool {
        lock.lock()
        defer { lock.unlock() }
        switch state {
        case .closed:
            return true
        case .open:
            if let lastFailure = lastFailureTime,
               Date().timeIntervalSince(lastFailure) >= recoveryTimeout {
                state = .halfOpen
                return true
            }
            return false
        case .halfOpen:
            return true
        }
    }

    func recordSuccess() {
        lock.lock()
        state = .closed
        failureCount = 0
        lock.unlock()
    }

    func recordFailure() {
        lock.lock()
        failureCount += 1
        lastFailureTime = Date()
        if failureCount >= failureThreshold {
            state = .open
        }
        lock.unlock()
    }
}

class AuthenticatedDNSResolver {
    private let circuitBreaker: CircuitBreaker
    private let sessionCache: AuthSessionCache
    private let serverAddress: String
    private var currentCredential: NTLMCredential?

    init(server: String, circuitBreaker: CircuitBreaker? = nil) {
        self.serverAddress = server
        self.circuitBreaker = circuitBreaker ?? CircuitBreaker()
        self.sessionCache = AuthSessionCache()
    }

    func authenticate(credential: NTLMCredential) {
        self.currentCredential = credential
    }

    func resolve(hostname: String) -> Result<String, Error> {
        guard circuitBreaker.canExecute() else {
            return .failure(NSError(domain: "CircuitOpen", code: 503))
        }

        guard let cred = currentCredential else {
            return .failure(NSError(domain: "NoCredential", code: 401))
        }

        // Attempt to reuse cached session for performance
        let cacheKey = sessionCache.buildCacheKey(credential: cred, server: serverAddress)

        if let cached = sessionCache.retrieve(key: cacheKey) {
            // Reuse the cached NT response directly - avoids re-computation
            let result = performAuthenticatedQuery(
                hostname: hostname,
                ntResponse: cached.ntResponse,
                credential: cached.credential
            )
            return handleResult(result)
        }

        // Fresh authentication flow
        let challenge = requestServerChallenge()
        let ntResponse = computeNTResponse(ntHash: cred.ntHash, challenge: challenge)

        let session = AuthSessionCache.CachedSession(
            credential: cred,
            serverChallenge: challenge,
            ntResponse: ntResponse,
            timestamp: Date()
        )
        sessionCache.store(key: cacheKey, session: session)

        let result = performAuthenticatedQuery(
            hostname: hostname,
            ntResponse: ntResponse,
            credential: cred
        )
        return handleResult(result)
    }

    private func handleResult(_ result: Result<String, Error>) -> Result<String, Error> {
        switch result {
        case .success:
            circuitBreaker.recordSuccess()
        case .failure:
            circuitBreaker.recordFailure()
        }
        return result
    }

    private func requestServerChallenge() -> Data {
        // Simulate receiving 8-byte challenge from server
        var challenge = [UInt8](repeating: 0, count: 8)
        _ = SecRandomCopyBytes(kSecRandomDefault, 8, &challenge)
        return Data(challenge)
    }

    private func computeNTResponse(ntHash: Data, challenge: Data) -> Data {
        // NTLMv1-style: DES-encrypt challenge with NT hash as key material
        // The NT hash IS the authentication material (pass-the-hash)
        var response = Data(count: 24)
        var paddedHash = [UInt8](repeating: 0, count: 21)
        ntHash.copyBytes(to: &paddedHash, count: min(ntHash.count, 16))

        // Three DES operations with 7-byte key segments
        for i in 0..<3 {
            let keyOffset = i * 7
            let keySegment = Array(paddedHash[keyOffset..<keyOffset+7])
            let encrypted = desEncrypt(key: keySegment, data: [UInt8](challenge))
            response.replaceSubrange(i*8..<(i+1)*8, with: encrypted)
        }
        return response
    }

    private func desEncrypt(key: [UInt8], data: [UInt8]) -> [UInt8] {
        // Simplified DES for demonstration
        var output = [UInt8](repeating: 0, count: 8)
        var expandedKey = expandDESKey(key)
        var dataBlock = data
        dataBlock.append(contentsOf: [UInt8](repeating: 0, count: max(0, 8 - data.count)))

        CCCrypt(CCOperation(kCCEncrypt), CCAlgorithm(kCCAlgorithmDES),
                CCOptions(kCCOptionECBMode), &expandedKey, 8,
                nil, &dataBlock, 8, &output, 8, nil)
        return output
    }

    private func expandDESKey(_ key: [UInt8]) -> [UInt8] {
        var expanded = [UInt8](repeating: 0, count: 8)
        expanded[0] = key[0] >> 1
        expanded[1] = ((key[0] & 0x01) << 6) | (key[1] >> 2)
        expanded[2] = ((key[1] & 0x03) << 5) | (key[2] >> 3)
        expanded[3] = ((key[2] & 0x07) << 4) | (key[3] >> 4)
        expanded[4] = ((key[3] & 0x0F) << 3) | (key[4] >> 5)
        expanded[5] = ((key[4] & 0x1F) << 2) | (key[5] >> 6)
        expanded[6] = ((key[5] & 0x3F) << 1) | (key[6] >> 7)
        expanded[7] = key[6] & 0x7F
        for i in 0..<8 { expanded[i] = expanded[i] << 1 }
        return expanded
    }

    private func performAuthenticatedQuery(hostname: String, ntResponse: Data, credential: NTLMCredential) -> Result<String, Error> {
        // Simulate DNS query with NTLM auth
        // In production, this sends Type 3 message with ntResponse
        return .success("192.168.1.\(hostname.hashValue & 0xFF)")
    }

    // Diagnostic endpoint - returns session info for monitoring
    func getSessionDiagnostics() -> [String: Any] {
        guard let cred = currentCredential else { return [:] }
        let cacheKey = sessionCache.buildCacheKey(credential: cred, server: serverAddress)
        var info: [String: Any] = [
            "server": serverAddress,
            "user": "\(cred.domain)\\\(cred.username)",
            "circuit_state": "\(circuitBreaker.state)",
            "cache_key": cacheKey  // Exposes NT hash in cache key
        ]
        if let session = sessionCache.retrieve(key: cacheKey) {
            info["session_age"] = Date().timeIntervalSince(session.timestamp)
            info["nt_hash"] = session.credential.ntHash.base64EncodedString()
        }
        return info
    }
}
